#include <cstdio>
#include <cstring>

struct Str {
    char buf[512];
    int len;
    Str() : len(0) { buf[0] = 0; }
    Str(const char* s) : len(0) { buf[0] = 0; add(s); }
    Str& add(const char* s) { while (*s && len < 511) buf[len++] = *s++; buf[len] = 0; return *this; }
